import type { FilterValue, Option } from 'models/Filters';
import {
  isHalfKey,
  isQuarterKey,
  resolveTimePeriodSelection,
  TimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

export interface TimePeriodDescriptionLabel {
  primaryLabel: string;
  rangeLabel: string;
}

interface GetTimePeriodDescriptionLabelParams {
  periodType: FilterValue | undefined;
  dtEnd: FilterValue | undefined;
  cutoffDate: string | null | undefined;
  periodTypes: Option[] | undefined;
}

export const getTimePeriodDescriptionLabel = ({
  periodType,
  dtEnd,
  cutoffDate,
  periodTypes,
}: GetTimePeriodDescriptionLabelParams): TimePeriodDescriptionLabel | null => {
  const selection = resolveTimePeriodSelection(periodType, dtEnd, cutoffDate);
  if (!selection) return null;

  const configuredLabel = periodTypes?.find(
    ({ value }) => value === selection.periodType,
  )?.label;
  if (typeof configuredLabel !== 'string' || !configuredLabel.trim()) {
    return null;
  }

  let selectionNumber = '';
  if (
    selection.periodType === TimePeriodType.HALF &&
    isHalfKey(selection.end)
  ) {
    selectionNumber = selection.end.slice(1);
  }
  if (
    selection.periodType === TimePeriodType.QTR &&
    isQuarterKey(selection.end)
  ) {
    selectionNumber = selection.end.slice(1);
  }

  return {
    primaryLabel: [configuredLabel, selectionNumber].filter(Boolean).join(' '),
    rangeLabel: selection.description,
  };
};
